import numpy as np
import time
import math

try:
    from scipy.optimize import minimize
    HAVE_SCIPY = True
except Exception:
    HAVE_SCIPY = False


def R_of_h(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0:
        return 0.0
    s = h.sum()
    if s <= 0:
        return 0.0
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def expand_blocks(blocks, N):
    K = len(blocks)
    idx = (np.arange(N) * K) // N
    return np.asarray(blocks, dtype=float)[idx]


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    edges = np.linspace(0.0, 1.0, N + 1) * M
    out = np.empty(N)
    cum = np.concatenate([[0.0], np.cumsum(h)])
    for i in range(N):
        x0 = edges[i]
        x1 = edges[i + 1]
        i0 = int(math.floor(x0))
        i1 = int(math.floor(x1))
        if i1 >= M:
            i1 = M - 1
        if i0 == i1:
            out[i] = h[min(i0, M - 1)]
        else:
            total = h[i0] * (i0 + 1 - x0)
            if i1 > i0 + 1:
                total += cum[i1] - cum[i0 + 1]
            total += h[min(i1, M - 1)] * (x1 - i1)
            out[i] = total / (x1 - x0)
    return out


def refine_blocks(K, N, budget_end, best_state):
    """Optimize K block heights (first fixed to 1) to maximize R."""
    def negR(logh):
        blocks = np.empty(K)
        blocks[0] = 1.0
        blocks[1:] = np.exp(np.clip(logh, -20, 20))
        return -R_of_h(expand_blocks(blocks, N))

    seeds = []
