def coordinate_refine(h, cur, budget_end, t0, N):
    """Coordinate descent on the full N-vector with adaptive step."""
    h = h.copy()
    step = 0.15
    while time.process_time() < budget_end and step > 1e-5:
        improved = False
        for i in range(N):
            if time.process_time() > budget_end:
                return h, cur
            old = h[i]
            for d in (step, -step):
