        after = best_state['R']
        print("stage K=%d: %.6f -> %.6f, %.2f s" % (K, before, after, time.process_time() - t0))

    # coordinate refine the best
    if time.process_time() < budget_end:
        before = best_state['R']
        h = np.asarray(best_state['blocks'], dtype=float).copy()
        if h.size != N:
            h = resample(expand_blocks(h, N), N)
        cur = R_of_h(h)
        h, cur = coordinate_refine(h, cur, budget_end, t0, N)
        if cur > best_state['R']:
            best_state['R'] = cur
            best_state['blocks'] = h.copy()
            keep_best(h)
        print("stage refine: %.6f -> %.6f, %.2f s" % (before, best_state['R'], time.process_time() - t0))

    # final return
    result = np.asarray(best_state['blocks'], dtype=float)
    if result.size != N:
        result = resample(expand_blocks(result, N), N)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and R_of_h(s) > R_of_h(result):
            result = s

    print("final R = %.6f, N = %d, %.2f s" % (R_of_h(result), result.size, time.process_time() - t0))
    return result

