def coordinate_refine(h, cur, budget_end, N, max_sweeps=50):
    """Coordinate descent with additive and multiplicative steps, shrinking."""
    h = h.copy()
    step = 0.15
    sweeps = 0
    while time.process_time() < budget_end and step > 1e-6 and sweeps < max_sweeps:
        sweeps += 1
        improved = False
        for i in range(N):
            if time.process_time() > budget_end:
                return h, cur
            old = h[i]
            # additive
            for d in (step, -step):
                h[i] = max(0.0, old + d)
                v = R_of_h(h)
                if v > cur + 1e-13:
                    cur = v
                    improved = True
                    break
                else:
                    h[i] = old
            if h[i] != old:
                continue
            # multiplicative
            for m in (1.0 + step, 1.0 / (1.0 + step)):
                h[i] = max(0.0, old * m)
                v = R_of_h(h)
                if v > cur + 1e-13:
                    cur = v
                    improved = True
                    break
                else:
                    h[i] = old
        if not improved:
            step *= 0.5
    return h, cur


def perturb_and_refine(h, cur, N, budget_end, n_trials, rng):
    """Random contiguous-block multiplicative perturbations + coordinate refine."""
    best_h = h.copy()
    best_v = cur
    for _ in range(n_trials):
        if time.process_time() > budget_end:
            break
        trial = h.copy()
        # 1-3 contiguous blocks, multiplicative factor
        nb = rng.integers(1, 4)
        for _b in range(nb):
            i0 = rng.integers(0, N)
            length = rng.integers(max(1, N // 20), max(2, N // 3))
            i1 = min(N, i0 + length)
            factor = math.exp(rng.normal(0.0, 0.25))
            trial[i0:i1] *= factor
        v = R_of_h(trial)
        # quick refine with small step
        trial, v = coordinate_refine(trial, v, budget_end, N, max_sweeps=8)
        if v > best_v + 1e-12:
            best_v = v
            best_h = trial.copy()
    return best_h, best_v


