    # also keep base's block-optimization stage as a fallback improvement
    best_state = {'R': gbest['R'], 'blocks': None, 'K': 0}
    if s is not None:
        best_state['blocks'] = np.asarray(s, dtype=float).copy()
        best_state['K'] = s.size

    print("stage init: %.6f -> %.6f, %.2f s" % (gbest['R'], gbest['R'], time.process_time() - t0))

    # Coarse-to-fine continuation
    levels = [25, 50, 100, 200, 400, 800, 1600]
