def R_and_grad(h):
    h = np.asarray(h, dtype=float)
    N = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(N)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]
    b = L[1:]
    dL = np.zeros(L.size)
    dL[:-1] += (2.0 * a + b) / 3.0
    dL[1:] += (a + 2.0 * b) / 3.0
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = L.max()
    kmax = int(np.argmax(L))
    if linf <= 0:
        return 0.0, np.zeros(N)
    R = l2sq / (l1 * linf)
    dL_int = dL[1:-1]
    corr = np.convolve(dL_int, h[::-1])
    g = 2.0 * corr[N:N + N]
    dL2sq = g
    dlinf = np.zeros(N)
    if 1 <= kmax <= 2 * N - 1:
        lo = max(0, kmax - N)
        hi = min(N - 1, kmax - 1)
        for i in range(lo, hi + 1):
            dlinf[i] = 2.0 * h[kmax - 1 - i]
    grad = dL2sq / (l1 * linf) - l2sq * (2.0 * s) / (l1 * l1 * linf) - l2sq * dlinf / (l1 * linf * linf)
    return R, grad


