# ---------- Gaussian-mixture parameterization ----------

def gmix_to_h(params, M, N):
    x = (np.arange(N) + 0.5) / N
    ped = params[0]
    a = params[1:1 + M]
    c = params[1 + M:1 + 2 * M]
    lw = params[1 + 2 * M:1 + 3 * M]
    w = np.exp(np.clip(lw, -6.0, 1.0))
    h = np.full(N, ped)
    for m in range(M):
        h += a[m] * np.exp(-0.5 * ((x - c[m]) / w[m]) ** 2)
    return np.clip(h, 0.0, None)


def optimize_gmix(M, N, x0, budget_end):
    def negR(p):
        h = gmix_to_h(p, M, N)
        return -R_of_h(h)
    if not HAVE_SCIPY:
        return x0, R_of_h(gmix_to_h(x0, M, N))
    try:
        res = minimize(negR, x0, method='Nelder-Mead',
                       options={'xatol': 1e-8, 'fatol': 1e-12,
                                'maxiter': 4000, 'maxfev': 8000})
        p = res.x
        return p, -res.fun
    except Exception:
        return x0, R_of_h(gmix_to_h(x0, M, N))


def random_gmix_init(M, rng):
    ped = 0.0 if rng.rand() < 0.5 else 0.05 * rng.rand()
    a = np.exp(rng.uniform(-1.0, 1.0, M))
    c = np.sort(rng.uniform(0.05, 0.95, M))
    lw = np.log(rng.uniform(0.02, 0.3, M))
    return np.concatenate([[ped], a, c, lw])


def sigma_ladder(h, sigmas, N, budget_end, best_state, maxiter=800):
    """Smooth + renorm + exact-R L-BFGS-B for each sigma; keep global best."""
    for sigma in sigmas:
        if time.process_time() > budget_end:
            break
        hs = smooth(h, sigma)
        if hs.sum() <= 0:
            continue
        hs = hs * (N / hs.sum())
        h2, v = lbfgsb_refine(hs, budget_end, maxiter=maxiter)
        if v > best_state['R']:
            best_state['R'] = v
            best_state['blocks'] = h2.copy()
            best_state['K'] = N
            keep_best(h2)
    return best_state


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget_end = t0 + 0.92 * budget_seconds
    N = 800

    best_state = {'R': -1.0, 'blocks': None, 'K': 0}

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            h0 = resample(s, N)
            best_state['R'] = R_of_h(h0)
            best_state['blocks'] = h0.copy()
            best_state['K'] = N
            keep_best(h0)
    if best_state['blocks'] is None:
        const = np.ones(N)
        best_state['R'] = R_of_h(const)
        best_state['blocks'] = const.copy()
        best_state['K'] = N
        keep_best(const)

    print("stage init: %.6f -> %.6f, %.2f s" % (best_state['R'], best_state['R'], time.process_time() - t0))

    # ---- EXPERIMENT: fine-sigma smooth + polish ladder on the start basin ----
    # Start from the given construction (p0057's N=3200 result).
    N1 = 3200
    if start is not None and np.asarray(start).size > 0:
        base_h = resample(np.asarray(start, dtype=float), N1)
    else:
        base_h = resample(best_state['blocks'], N1)
    base_h = np.clip(base_h, 0.0, None)
    if base_h.sum() <= 0:
        base_h = np.ones(N1)
    base_h = base_h * (N1 / base_h.sum())
    v0 = R_of_h(base_h)
    if v0 > best_state['R']:
        best_state['R'] = v0
        best_state['blocks'] = base_h.copy()
        best_state['K'] = N1
        keep_best(base_h)
    print("  base at N=%d: R = %.6f" % (N1, v0))

    before = best_state['R']
    sigmas1 = [0, 0.5, 1, 2, 3, 4, 6]
    sigma_ladder(base_h, sigmas1, N1, budget_end, best_state, maxiter=800)
    print("stage sigma-ladder N=%d: %.6f -> %.6f, %.2f s" % (N1, before, best_state['R'], time.process_time() - t0))

    # Second pass at the best sigma (re-run the winning sigma from the current best)
    if time.process_time() < budget_end:
        before = best_state['R']
        # find best sigma by trying each once more from current best
        h_cur = best_state['blocks'].copy()
        best_sig = 0.0
        best_v = -1.0
        for sigma in sigmas1:
            if time.process_time() > budget_end:
                break
            hs = smooth(h_cur, sigma)
            if hs.sum() <= 0:
                continue
            hs = hs * (N1 / hs.sum())
            _, v = lbfgsb_refine(hs, budget_end, maxiter=400)
            if v > best_v:
                best_v = v
                best_sig = sigma
        # now polish at best_sig with full maxiter
        hs = smooth(h_cur, best_sig)
        if hs.sum() > 0:
            hs = hs * (N1 / hs.sum())
            h2, v = lbfgsb_refine(hs, budget_end, maxiter=800)
            if v > best_state['R']:
                best_state['R'] = v
                best_state['blocks'] = h2.copy()
                best_state['K'] = N1
                keep_best(h2)
        print("stage sigma-2nd (sig=%.1f) N=%d: %.6f -> %.6f, %.2f s" % (best_sig, N1, before, best_state['R'], time.process_time() - t0))

    # ---- Upsample best to N=6400 and run a sigma ladder ----
    if time.process_time() < budget_end:
        before = best_state['R']
        N2 = 6400
        h_up = resample(best_state['blocks'], N2)
        h_up = np.clip(h_up, 0.0, None)
        if h_up.sum() > 0:
            h_up = h_up * (N2 / h_up.sum())
            sigmas2 = [1.5, 2.2, 3.2]
            sigma_ladder(h_up, sigmas2, N2, budget_end, best_state, maxiter=800)
        print("stage sigma-ladder N=%d: %.6f -> %.6f, %.2f s" % (N2, before, best_state['R'], time.process_time() - t0))

    # ---- If budget remains, continue base's block optimization at increasing resolution ----
    for K in [6, 7, 8, 9, 10, 11, 12]:
        if time.process_time() > budget_end:
            break
        before = best_state['R']
        refine_blocks(K, N, budget_end, best_state)
        after = best_state['R']
        print("stage K=%d: %.6f -> %.6f, %.2f s" % (K, before, after, time.process_time() - t0))

    # ---- N=400 restarts from small random perturbations ----
    rng2 = np.random.RandomState(12345)
    restart = 0
    while time.process_time() < budget_end:
        restart += 1
        before = best_state['R']
        h = resample(best_state['blocks'], 400)
        scale = 0.02 * (1.0 + 0.5 * rng2.rand())
        h = h * (1.0 + scale * rng2.randn(h.size))
        h = np.clip(h, 0.0, None)
        if h.sum() <= 0:
            continue
        cur = R_of_h(h)
        h, cur = coordinate_refine(h, cur, budget_end, step0=0.05, step_min=1e-5)
        if cur > best_state['R']:
            best_state['R'] = cur
            best_state['blocks'] = h.copy()
            keep_best(h)
        if restart % 3 == 0:
            print("stage restart%d: %.6f -> %.6f, %.2f s" % (restart, before, best_state['R'], time.process_time() - t0))

    print("final R = %.6f, N = %d, %.2f s" % (best_state['R'], best_state['blocks'].size, time.process_time() - t0))
    return np.asarray(best_state['blocks'], dtype=float)
